parameters.jsCode:
const raw = $json.message.content;
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/); // grab the JSON object even if the model added extra text
  parsed = JSON.parse(match[0]);
} catch (e) {
  return [{ json: { error: true, raw } }];
}
return [{ json: { content: parsed.content, due_at: parsed.due_at } }];

